head.script:
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};



scwin.onpageload = function () {
    // 사전 조건은 dataList 정적 데이터로 세팅됨 (추가 처리 없음)
};



// type 값별 CSV 다운로드 (파일명을 달리해 구분)
scwin.saveByType = function (strType, strFileName) {
    var options = { fileName : strFileName, delim : "," };

    if (strType !== "") {
        options.type = strType;
    }

    grd_type.saveCSV(options);
    scwin.setReturnValue("실행 : type=" + (strType === "" ? "생략" : "'" + strType + "'") + " → 다운로드 파일 " + strFileName);
};

// ① type 생략 (기본값 "1")
scwin.btn_save_default_onclick = function () {
    scwin.saveByType("", "saveCSV_default.csv");
};

// ② type = "0"
scwin.btn_save_type0_onclick = function () {
    scwin.saveByType("0", "saveCSV_type0.csv");
};

// ③ type = "1"
scwin.btn_save_type1_onclick = function () {
    scwin.saveByType("1", "saveCSV_type1.csv");
};

// ④ type = "2"
scwin.btn_save_type2_onclick = function () {
    scwin.saveByType("2", "saveCSV_type2.csv");
};
